import { Box, Paper, Popper, ThemeProvider, useTheme } from '@mui/material'
import type { PopperPlacementType, PopperProps, SxProps, Theme } from '@mui/material'
import { useCallback, useEffect, useLayoutEffect, useMemo, useRef, useState } from 'react'
import type { CSSProperties, KeyboardEvent as ReactKeyboardEvent, PointerEvent as ReactPointerEvent, ReactNode } from 'react'
import { dialogService } from '../services/dialog_service'
import type { ResizeCorner } from './resizable_popover'

interface PopperSize {
    height?: number
    width?: number
}

interface MinimumPopperSize {
    height: number
    width: number
}

interface PopperPosition {
    left: number
    top: number
}

interface ResizablePopperBaseProps {
    anchorElement: HTMLElement | null
    children: ReactNode
    constrainSizeToViewport?: boolean
    draggable?: boolean
    focusOnMount?: boolean
    fullHeight?: boolean
    initialSize: PopperSize
    labelId: string
    minimumSize?: MinimumPopperSize
    onActivate?: () => void
    open: boolean
    paperSx?: SxProps<Theme>
    persistSizeOnResizeEndOnly?: boolean
    placement?: PopperPlacementType
    resizeCorner?: ResizeCorner
    resizeFromAllSides?: boolean
    resizeLabel: string
    stackPosition?: number
    storageKey?: string
}

type ResizablePopperProps = ResizablePopperBaseProps & ({
    closeOnEscape: false
    onClose?: never
} | {
    closeOnEscape?: true
    onClose: () => void
})

// Controls that must keep their own click even when they sit inside a drag handle.
// MUI selects render a div[role="combobox"], so native tag names alone are not enough.
const INTERACTIVE_SELECTOR = [
    'button', 'input', 'select', 'textarea', 'a', 'label',
    '[role="button"]', '[role="combobox"]', '[role="option"]', '[role="listbox"]', '[role="tab"]', '[role="switch"]',
    '[contenteditable="true"]',
].join(', ')
const MIN_WIDTH = 280
const MIN_HEIGHT = 200
const HANDLE_SIZE = 16
const EDGE_HANDLE_SIZE = 6
const VIEWPORT_MARGIN = 16
const OVERLAY_LAYER_OFFSET = 1
const ALL_RESIZE_DIRECTIONS = ['top', 'right', 'bottom', 'left', 'top-right', 'bottom-right', 'bottom-left', 'top-left'] as const
type ResizeDirection = typeof ALL_RESIZE_DIRECTIONS[number]

const PREVENT_VIEWPORT_OVERFLOW_MODIFIER = { name: 'preventOverflow', options: { altAxis: true, padding: VIEWPORT_MARGIN, tether: false } } as const
const VIEWPORT_MODIFIERS: NonNullable<PopperProps['modifiers']> = [
    PREVENT_VIEWPORT_OVERFLOW_MODIFIER,
    { name: 'flip', options: { padding: VIEWPORT_MARGIN } },
]
const FULL_HEIGHT_VIEWPORT_MODIFIERS: NonNullable<PopperProps['modifiers']> = [PREVENT_VIEWPORT_OVERFLOW_MODIFIER]
const VIEWPORT_POPPER_OPTIONS: NonNullable<PopperProps['popperOptions']> = { strategy: 'fixed' }

function clampSizeToViewport(size: PopperSize, minimumSize: MinimumPopperSize) {
    const maximumHeight = Math.max(0, window.innerHeight - VIEWPORT_MARGIN * 2)
    const maximumWidth = Math.max(0, window.innerWidth - VIEWPORT_MARGIN * 2)
    const minimumHeight = Math.min(minimumSize.height, maximumHeight)
    const minimumWidth = Math.min(minimumSize.width, maximumWidth)

    return {
        height: Math.min(Math.max(size.height as number, minimumHeight), maximumHeight),
        width: Math.min(Math.max(size.width as number, minimumWidth), maximumWidth),
    }
}

function loadSize(
    initialSize: PopperSize,
    minimumSize: MinimumPopperSize,
    constrainSizeToViewport: boolean,
    storageKey?: string,
): PopperSize {
    if (!storageKey) return initialSize

    const storedValue = window.localStorage.getItem(storageKey)
    if (!storedValue) return initialSize

    try {
        const storedSize = JSON.parse(storedValue) as Partial<PopperSize>
        if (!Number.isFinite(storedSize.height) || !Number.isFinite(storedSize.width)) return initialSize

        const size = {
            height: Math.max(minimumSize.height, storedSize.height as number),
            width: Math.max(minimumSize.width, storedSize.width as number),
        }

        return constrainSizeToViewport ? clampSizeToViewport(size, minimumSize) : size
    } catch {
        return initialSize
    }
}

function directionCursor(direction: ResizeDirection) {
    if (direction === 'top' || direction === 'bottom') return 'ns-resize'
    if (direction === 'left' || direction === 'right') return 'ew-resize'
    if (direction === 'top-right' || direction === 'bottom-left') return 'nesw-resize'
    return 'nwse-resize'
}

function directionPosition(direction: ResizeDirection) {
    const isCorner = direction.includes('-')
    const touchesTop = direction.startsWith('top')
    const touchesBottom = direction.startsWith('bottom')
    const touchesLeft = direction.endsWith('left') || direction === 'left'
    const touchesRight = direction.endsWith('right') || direction === 'right'

    return {
        bottom: touchesBottom ? 0 : undefined,
        cursor: directionCursor(direction),
        height: isCorner ? HANDLE_SIZE : touchesTop || touchesBottom ? EDGE_HANDLE_SIZE : `calc(100% - ${HANDLE_SIZE * 2}px)`,
        left: touchesLeft ? 0 : direction === 'top' || direction === 'bottom' ? HANDLE_SIZE : undefined,
        right: touchesRight ? 0 : undefined,
        top: touchesTop ? 0 : direction === 'left' || direction === 'right' ? HANDLE_SIZE : undefined,
        width: isCorner ? HANDLE_SIZE : touchesLeft || touchesRight ? EDGE_HANDLE_SIZE : `calc(100% - ${HANDLE_SIZE * 2}px)`,
    }
}

function clampDetachedLeft(left: number, width: number) {
    return Math.min(Math.max(0, left), Math.max(0, window.innerWidth - width))
}

function clampDetachedTop(top: number, height: number) {
    return Math.min(Math.max(0, top), Math.max(0, window.innerHeight - height))
}

function centeredPosition(size: PopperSize): PopperPosition {
    const width = size.width ?? MIN_WIDTH
    const height = size.height ?? MIN_HEIGHT

    return {
        left: clampDetachedLeft((window.innerWidth - width) / 2, width),
        top: clampDetachedTop((window.innerHeight - height) / 2, height),
    }
}

/** A non-modal anchored surface with configurable drag handles for resizing its content. */
export function ResizablePopper(props: ResizablePopperProps) {
    const {
        anchorElement,
        children,
        closeOnEscape = true,
        constrainSizeToViewport = false,
        draggable = false,
        focusOnMount: focusOnMountProp,
        fullHeight = false,
        initialSize,
        labelId,
        minimumSize = { height: MIN_HEIGHT, width: MIN_WIDTH },
        onActivate,
        onClose,
        open,
        paperSx,
        persistSizeOnResizeEndOnly = false,
        placement = 'bottom-start',
        resizeCorner = 'lower-right',
        resizeFromAllSides = false,
        resizeLabel,
        stackPosition,
        storageKey,
    } = props
    const focusOnMount = focusOnMountProp ?? stackPosition !== undefined
    const [size, setSize] = useState(() => loadSize(initialSize, minimumSize, constrainSizeToViewport, storageKey))
    const [position, setPosition] = useState<PopperPosition | null>(() => draggable && !anchorElement ? centeredPosition(size) : null)
    const [detachedLeft, setDetachedLeft] = useState<number | null>(null)
    const anchoredLeftRef = useRef<number | null>(null)
    const focusOnMountRef = useRef(focusOnMount)
    const paperRef = useRef<HTMLDivElement | null>(null)
    const resizeRef = useRef<AbortController | null>(null)
    const theme = useTheme()
    const overlayTheme = useMemo<Theme>(() => ({
        ...theme,
        zIndex: {
            ...theme.zIndex,
            modal: theme.zIndex.modal + (stackPosition ?? 0) + OVERLAY_LAYER_OFFSET,
        },
    }), [stackPosition, theme])

    useEffect(() => () => resizeRef.current?.abort(), [])
    const setPaperElement = useCallback((element: HTMLDivElement | null) => {
        paperRef.current = element
        if (!element || !focusOnMountRef.current) return

        focusOnMountRef.current = false
        element.focus()
    }, [])
    useEffect(() => {
        if (!storageKey || persistSizeOnResizeEndOnly) return

        window.localStorage.setItem(storageKey, JSON.stringify(size))
    }, [persistSizeOnResizeEndOnly, size, storageKey])
    useLayoutEffect(() => {
        if (!fullHeight || !paperRef.current) return

        const bounds = paperRef.current.getBoundingClientRect()
        const width = size.width ?? bounds.width
        const anchoredLeft = anchoredLeftRef.current ?? bounds.left
        setDetachedLeft(clampDetachedLeft(anchoredLeft, width))
    }, [fullHeight, size.width])
    useEffect(() => {
        if (!fullHeight) return

        const handleViewportResize = () => {
            setDetachedLeft((current) => current === null ? current : clampDetachedLeft(current, size.width ?? MIN_WIDTH))
        }
        window.addEventListener('resize', handleViewportResize)

        return () => window.removeEventListener('resize', handleViewportResize)
    }, [fullHeight, size.width])
    useEffect(() => {
        if (!draggable || fullHeight) return

        const handleViewportResize = () => {
            setPosition((current) => current ? {
                left: clampDetachedLeft(current.left, size.width ?? MIN_WIDTH),
                top: clampDetachedTop(current.top, size.height ?? MIN_HEIGHT),
            } : current)
        }
        window.addEventListener('resize', handleViewportResize)

        return () => window.removeEventListener('resize', handleViewportResize)
    }, [draggable, fullHeight, size])

    const handleKeyDown = (event: ReactKeyboardEvent<HTMLDivElement>) => {
        if (event.key !== 'Escape' || !closeOnEscape) return

        resizeRef.current?.abort()
        onClose?.()
    }

    const handlePaperClickCapture = () => {
        if (fullHeight || !paperRef.current) return

        anchoredLeftRef.current = paperRef.current.getBoundingClientRect().left
    }

    const startDrag = (event: ReactPointerEvent) => {
        onActivate?.()

        try {
            if (!draggable || fullHeight) return

            const target = event.target
            if (!(target instanceof Element) || !target.closest('[data-drag-handle="true"]')) return
            if (target.closest(INTERACTIVE_SELECTOR)) return

            event.preventDefault()
            resizeRef.current?.abort()
            if (!paperRef.current) throw new Error('Missing draggable popper paper element')

            const controller = new AbortController()
            const bounds = paperRef.current.getBoundingClientRect()
            const start = { left: bounds.left, top: bounds.top, x: event.clientX, y: event.clientY }
            resizeRef.current = controller

            window.addEventListener('pointermove', (move: PointerEvent) => {
                const width = size.width ?? bounds.width
                const height = size.height ?? bounds.height
                setPosition({
                    left: clampDetachedLeft(start.left + move.clientX - start.x, width),
                    top: clampDetachedTop(start.top + move.clientY - start.y, height),
                })
            }, { signal: controller.signal })
            window.addEventListener('pointerup', () => controller.abort(), { signal: controller.signal })
        } catch (error) {
            resizeRef.current?.abort()
            dialogService.error(error, { fallbackMessage: 'Popup drag could not be started' })
        }
    }

    const startResize = (event: ReactPointerEvent) => {
        try {
            event.preventDefault()
            resizeRef.current?.abort()

            if (!paperRef.current) throw new Error('Missing resizable popper paper element')

            const direction = event.currentTarget.getAttribute('data-direction') as ResizeDirection | null
            const controller = new AbortController()
            const bounds = paperRef.current.getBoundingClientRect()
            const start = {
                height: size.height ?? bounds.height,
                left: bounds.left,
                top: bounds.top,
                width: size.width ?? bounds.width,
                x: event.clientX,
                y: event.clientY,
            }
            let completedSize = { height: start.height, width: start.width }
            resizeRef.current = controller

            window.addEventListener('pointermove', (move: PointerEvent) => {
                const activeDirection = direction ?? (resizeCorner === 'lower-left' ? 'bottom-left' : 'bottom-right')
                const horizontalDelta = move.clientX - start.x
                const verticalDelta = move.clientY - start.y
                const resizesLeft = activeDirection.includes('left')
                const resizesRight = activeDirection.includes('right')
                const resizesTop = activeDirection.includes('top')
                const resizesBottom = activeDirection.includes('bottom')
                const nextSize = {
                    height: Math.max(
                        minimumSize.height,
                        start.height + (resizesTop ? -verticalDelta : resizesBottom ? verticalDelta : 0),
                    ),
                    width: Math.max(
                        minimumSize.width,
                        start.width + (resizesLeft ? -horizontalDelta : resizesRight ? horizontalDelta : 0),
                    ),
                }
                const { height, width } = constrainSizeToViewport
                    ? clampSizeToViewport(nextSize, minimumSize)
                    : nextSize

                completedSize = { height, width }
                setSize({ height, width })
                if (draggable) {
                    const left = resizesLeft ? start.left + start.width - width : start.left
                    const top = resizesTop ? start.top + start.height - height : start.top
                    setPosition({ left: clampDetachedLeft(left, width), top: clampDetachedTop(top, height) })
                }
            }, { signal: controller.signal })
            window.addEventListener('pointerup', () => {
                if (storageKey && persistSizeOnResizeEndOnly) {
                    window.localStorage.setItem(storageKey, JSON.stringify(completedSize))
                }
                controller.abort()
            }, { signal: controller.signal })
        } catch (error) {
            resizeRef.current?.abort()
            dialogService.error(error, { fallbackMessage: 'Popup resize could not be started' })
        }
    }

    const paperStyle: CSSProperties = fullHeight
        ? { height: '100vh', left: detachedLeft ?? 0, position: 'fixed', top: 0, width: size.width }
        : position
            ? { ...size, left: position.left, position: 'fixed', top: position.top }
            : size
    const detached = position !== null || fullHeight

    return (
        <Popper
            anchorEl={anchorElement ?? (draggable ? document.body : null)}
            modifiers={fullHeight ? FULL_HEIGHT_VIEWPORT_MODIFIERS : VIEWPORT_MODIFIERS}
            open={open}
            placement={placement}
            popperOptions={VIEWPORT_POPPER_OPTIONS}
            sx={{
                left: detached ? '0 !important' : undefined,
                top: detached ? '0 !important' : undefined,
                transform: detached ? 'none !important' : undefined,
                zIndex: stackPosition === undefined ? 'modal' : (theme) => theme.zIndex.modal + stackPosition,
            }}
        >
            <Paper
                aria-labelledby={labelId}
                data-full-height={fullHeight ? 'true' : undefined}
                onClickCapture={handlePaperClickCapture}
                onFocusCapture={onActivate}
                onKeyDown={handleKeyDown}
                onPointerDownCapture={startDrag}
                ref={setPaperElement}
                role="dialog"
                style={paperStyle}
                tabIndex={stackPosition === undefined ? undefined : -1}
                sx={[{
                    display: 'flex',
                    maxHeight: fullHeight ? '100vh' : 'calc(100vh - 32px)',
                    maxWidth: fullHeight ? '100vw' : 'calc(100vw - 32px)',
                    overflow: 'hidden',
                    position: 'relative',
                }, paperSx] as SxProps<Theme>}
            >
                {stackPosition === undefined
                    ? children
                    : <ThemeProvider theme={overlayTheme}>{children}</ThemeProvider>}
                {!fullHeight && resizeFromAllSides ? ALL_RESIZE_DIRECTIONS.map((direction) => (
                    <Box
                        aria-label={`${resizeLabel} from ${direction}`}
                        data-direction={direction}
                        key={direction}
                        onPointerDown={startResize}
                        role="separator"
                        sx={{ ...directionPosition(direction), position: 'absolute', touchAction: 'none' }}
                    />
                )) : !fullHeight ? (
                    <Box
                        aria-label={resizeLabel}
                        data-corner={resizeCorner}
                        onPointerDown={startResize}
                        role="separator"
                        sx={{
                            bottom: 0,
                            cursor: resizeCorner === 'lower-left' ? 'nesw-resize' : 'nwse-resize',
                            height: HANDLE_SIZE,
                            left: resizeCorner === 'lower-left' ? 0 : undefined,
                            position: 'absolute',
                            right: resizeCorner === 'lower-right' ? 0 : undefined,
                            touchAction: 'none',
                            width: HANDLE_SIZE,
                        }}
                    />
                ) : null}
            </Paper>
        </Popper>
    )
}

import { Box, IconButton, Stack, Tooltip, Typography, useMediaQuery, useTheme } from '@mui/material'
import ArrowCollapseVertical from 'mdi-material-ui/ArrowCollapseVertical'
import ArrowExpandVertical from 'mdi-material-ui/ArrowExpandVertical'
import Close from 'mdi-material-ui/Close'
import { useMemo } from 'react'
import { actionContextIdentity, type ActionContext } from '../../../../data/action_context'
import type { ActionDefinition } from '../../../../data/action_types'
import { worktreeService } from '../../../../services/project/worktree_service'
import {
    actionRunSettingsService,
    createSessionActionRunSettingsStore,
} from '../../../../services/actions/action_run_settings_service'
import { ResizablePopper } from '../../../resizable_popper'
import type { WorktreeAssignmentTarget } from '../../../worktree_selector'
import { ActionAgentApprovals } from '../../agent/action_agent_approvals'
import { ActionAgentInteractionVisibility } from '../../agent/action_agent_interaction_visibility'
import { ActionAgentPromptOwner } from '../../agent/action_agent_prompt_owner'
import { ActionAgentQuestionOwner } from '../../agent/action_agent_question_owner'
import { ActionAgentSelectorsOwner } from '../../agent/action_agent_selectors_owner'
import { ActionConversationChatOwner } from '../../conversation/action_conversation_chat_owner'
import { ActionConversationPickerOwner } from '../../conversation/action_conversation_picker_owner'
import { ActionConversationStore } from '../../conversation/action_conversation_store'
import { ActionHistoryStore } from '../state/action_history_store'
import { ActionLogErrorOwner } from '../../conversation/action_log_error_owner'
import { ActionPopupBottomRow } from './action_popup_bottom_row'
import { ActionRunDisabledMessage } from './action_run_disabled_message'
import { ActionRunHistoryOwner } from '../state/action_run_history_owner'
import { ActionRunInputStore } from '../state/action_run_input_store'
import { ActionRunResultStore } from '../state/action_run_result_store'
import { ActionRunStatusOwner } from '../state/action_run_status_owner'
import { ActionScheduleOwner } from '../schedule/action_schedule_owner'
import { ActionScheduleStore } from '../schedule/action_schedule_store'
import { ActionSelector } from './action_selector'
import { ActionWorktreeSelectorOwner } from './action_worktree_selector_owner'
import { MarkdownTypeaheadLayerProvider } from '../../../editor/markdown_typeahead_layer_provider'

export const CARD_RUN_POPUP_SIZE_STORAGE_KEY = 'md2.cardRunPopupSize'
export const PROJECT_AGENT_POPUP_SIZE_STORAGE_KEY = 'md2.projectAgentPopupSize'

interface ActionPopupBindings {
    conversationStore: ActionConversationStore
    historyStore: ActionHistoryStore
    inputStore: ActionRunInputStore
    resultStore: ActionRunResultStore
    scheduleStore: ActionScheduleStore
}

function createActionPopupBindings(action: ActionDefinition, context: ActionContext): ActionPopupBindings {
    return {
        conversationStore: new ActionConversationStore(action.id, context),
        historyStore: new ActionHistoryStore(action, context),
        inputStore: new ActionRunInputStore(),
        resultStore: new ActionRunResultStore(),
        scheduleStore: new ActionScheduleStore(),
    }
}

interface ActionPopupContentProps {
    action: ActionDefinition
    actions: ActionDefinition[]
    anchorElement: HTMLElement | null
    assignmentContext: ActionContext
    baseContext: ActionContext
    draggable?: boolean
    fullHeight: boolean
    onActivate?: () => void
    onClose: () => void
    onSelectAction: (actionId: string) => void
    onToggleFullHeight: () => void
    open: boolean
    popupEntryId?: string
    primaryPath: string | null
    readOnlyMessage: string | null
    stackPosition?: number
    target: string | null
    titleId: string
}

/**
 * The message is rebuilt on every render but only reads the worktree list on the failing
 * path, so the popup never subscribes to worktree changes to keep a message it rarely shows.
 */
function worktreeValidationMessage(action: ActionDefinition, context: ActionContext) {
    const hasWorktreeAssignment = context.worktree !== undefined || !!context.worktreeError
    if (!hasWorktreeAssignment && !action.needsWorkTree) return null
    if (context.kind !== 'card' && context.kind !== 'project') {
        const reason = action.needsWorkTree ? 'when needsWorkTree is set' : 'for a worktree run'
        return `Action "${action.label}" requires card or project context ${reason}`
    }
    if (context.worktreeError) return context.worktreeError
    if (context.worktree === undefined) return `Action "${action.label}" requires a worktree assignment`
    if (!/^[1-9]\d*$/u.test(context.worktree)) return `Invalid worktree index: ${context.worktree}`

    const worktree = Number.parseInt(context.worktree, 10)
    if (!Number.isSafeInteger(worktree)) return `Invalid worktree index: ${context.worktree}`
    const record = worktreeService.getRecords()[worktree - 1]
    if (!record) return `Configured worktree ${worktree} does not exist`
    if (!record.valid) return `Configured worktree ${worktree} is invalid: ${record.error}`

    return null
}

function worktreeAssignmentTarget(context: ActionContext): WorktreeAssignmentTarget | null {
    if (context.kind === 'project') return { kind: 'project' }
    if ((context.kind === 'card' || context.kind === 'file') && context.file) return { kind: 'card', path: context.file }

    return null
}

/** Presentation and run behavior for the internally selected popup action. */
export function ActionPopupContent(props: ActionPopupContentProps) {
    const {
        action, actions, anchorElement, assignmentContext, baseContext, draggable, fullHeight, onActivate,
        onClose, onSelectAction, onToggleFullHeight, open, primaryPath, stackPosition, target, titleId,
        popupEntryId, readOnlyMessage,
    } = props
    const theme = useTheme()
    const isMobile = useMediaQuery(theme.breakpoints.down('md'))
    const settingsContextIdentity = actionContextIdentity(assignmentContext)
    const settingsStore = useMemo(
        () => assignmentContext.cardInternalId
            ? actionRunSettingsService.getCardStore(assignmentContext.cardInternalId, action.id)
            : createSessionActionRunSettingsStore(action.id, settingsContextIdentity),
        [action.id, assignmentContext.cardInternalId, settingsContextIdentity],
    )
    const bindings = useMemo(
        () => createActionPopupBindings(action, assignmentContext),
        [action, assignmentContext],
    )
    const { conversationStore, historyStore, inputStore, resultStore, scheduleStore } = bindings
    const runValidationError = worktreeValidationMessage(action, assignmentContext)
    const sizeStorageKey = baseContext.kind === 'project'
        ? PROJECT_AGENT_POPUP_SIZE_STORAGE_KEY
        : CARD_RUN_POPUP_SIZE_STORAGE_KEY
    const parsedWorktree = assignmentContext.worktree && /^[1-9]\d*$/u.test(assignmentContext.worktree)
        ? Number.parseInt(assignmentContext.worktree, 10)
        : null
    const worktreeAssignment = {
        worktree: parsedWorktree,
        worktreeError: assignmentContext.worktreeError ?? null,
        worktreeValue: assignmentContext.worktree ?? null,
    }
    const assignmentTarget = baseContext.kind === 'card' || baseContext.kind === 'file' || baseContext.kind === 'project'
        ? worktreeAssignmentTarget(baseContext)
        : null
    return (
        <ResizablePopper
            anchorElement={anchorElement}
            draggable={isMobile ? false : draggable}
            fullHeight={isMobile || fullHeight}
            initialSize={{ height: 450, width: 400 }}
            labelId={titleId}
            onActivate={onActivate}
            onClose={onClose}
            open={open}
            paperSx={{
                bgcolor: 'background.paper',
                border: 1,
                borderColor: 'divider',
                borderRadius: isMobile ? 0 : '14px',
                boxShadow: '0 24px 60px rgba(16,24,40,0.28)',
                flexDirection: 'column',
                height: isMobile ? '100vh !important' : undefined,
                left: isMobile ? '0 !important' : undefined,
                margin: isMobile ? '0 !important' : undefined,
                maxHeight: isMobile ? 'none' : undefined,
                maxWidth: isMobile ? 'none' : undefined,
                top: isMobile ? '0 !important' : undefined,
                transform: isMobile ? 'none !important' : undefined,
                width: isMobile ? '100vw !important' : undefined,
            }}
            resizeFromAllSides
            resizeLabel="Resize action popup"
            stackPosition={stackPosition}
            storageKey={isMobile ? undefined : sizeStorageKey}
        >
            <MarkdownTypeaheadLayerProvider stackPosition={stackPosition ?? 0}>
                <Typography
                    id={titleId}
                    sx={{ clip: 'rect(0 0 0 0)', clipPath: 'inset(50%)', height: 1, overflow: 'hidden', position: 'absolute', whiteSpace: 'nowrap', width: 1 }}
                >
                    {target ? `Run actions for ${target}` : 'Run actions'}
                </Typography>
                <Box
                    data-drag-handle={!isMobile && draggable ? 'true' : undefined}
                    sx={{
                        borderBottom: 1, borderColor: 'divider', cursor: !isMobile && draggable ? 'move' : undefined,
                        display: 'flex', flexDirection: 'column', flexShrink: 0, gap: 1, px: 1.5, py: 1.5,
                    }}
                >
                    <Box data-testid="action-popup-toolbar" sx={{ alignItems: 'center', display: 'flex', gap: 1 }}>
                        {target ? (
                            <Box
                                component="span"
                                sx={{
                                    bgcolor: 'custom.primaryBg', borderRadius: '5px', color: 'primary.main', flexShrink: 0,
                                    fontFamily: '"Roboto Mono", ui-monospace, monospace', fontSize: 11.5, fontWeight: 600,
                                    px: 0.875, py: 0.25,
                                }}
                            >
                                {target}
                            </Box>
                        ) : null}
                        {assignmentTarget && !readOnlyMessage ? (
                            <ActionWorktreeSelectorOwner
                                actionId={action.id}
                                assignment={worktreeAssignment}
                                assignmentTarget={assignmentTarget}
                                context={assignmentContext}
                                primaryPath={primaryPath}
                            />
                        ) : null}
                        {action.type === 'agent' ? (
                            <ActionConversationPickerOwner
                                actionId={action.id}
                                context={assignmentContext}
                                store={conversationStore}
                            />
                        ) : null}
                        <Box sx={{ flex: 1 }} />
                        {!isMobile ? (
                            <Tooltip title={fullHeight ? 'Collapse downward' : 'Expand upward'}>
                                <IconButton
                                    aria-label={fullHeight ? 'Collapse downward' : 'Expand upward'}
                                    onClick={onToggleFullHeight}
                                    size="small"
                                    sx={{ flexShrink: 0, height: 30, width: 30 }}
                                >
                                    {fullHeight
                                        ? <ArrowCollapseVertical sx={{ fontSize: 18 }} />
                                        : <ArrowExpandVertical sx={{ fontSize: 18 }} />}
                                </IconButton>
                            </Tooltip>
                        ) : null}
                        <IconButton aria-label="Close" onClick={onClose} size="small" sx={{ flexShrink: 0, height: 30, width: 30 }}>
                            <Close sx={{ fontSize: 18 }} />
                        </IconButton>
                    </Box>
                    <ActionSelector
                        actions={actions}
                        context={assignmentContext}
                        onSelect={onSelectAction}
                        selectedAction={action}
                    />
                </Box>
                {readOnlyMessage ? (
                    <Stack data-testid="action-popup-scroll-body" spacing={2} sx={{ flex: 1, minHeight: 0, overflow: 'auto', px: 1.5, py: 1 }}>
                        {action.type === 'agent' ? (
                            <ActionConversationChatOwner
                                actionId={action.id}
                                context={assignmentContext}
                                popupEntryId={popupEntryId}
                                store={conversationStore}
                            />
                        ) : null}
                        <Typography color="text.secondary" role="note" variant="caption">{readOnlyMessage}</Typography>
                    </Stack>
                ) : <>
                    <Stack data-testid="action-popup-scroll-body" spacing={2} sx={{ flex: 1, minHeight: 0, overflow: 'auto', px: 1.5, py: 1 }}>
                        <ActionAgentInteractionVisibility action={action} context={assignmentContext}>
                            <Stack spacing={1} sx={{ flex: 1, minHeight: 0 }}>
                                <Box sx={{ alignItems: 'center', color: 'text.secondary', display: 'flex', flexWrap: 'wrap', fontSize: 12, gap: 0.75 }}>
                                    {action.type === 'agent' ? (
                                        <ActionAgentSelectorsOwner
                                            action={action}
                                            context={assignmentContext}
                                            settingsStore={settingsStore}
                                        />
                                    ) : null}
                                    <ActionLogErrorOwner actionId={action.id} context={assignmentContext} resultStore={resultStore} />
                                </Box>
                                <ActionConversationChatOwner
                                    actionId={action.id}
                                    context={assignmentContext}
                                    popupEntryId={popupEntryId}
                                    store={conversationStore}
                                />
                                <ActionAgentPromptOwner
                                    action={action}
                                    context={assignmentContext}
                                    conversationStore={conversationStore}
                                    historyStore={historyStore}
                                    inputStore={inputStore}
                                    settingsStore={settingsStore}
                                    resultStore={resultStore}
                                    runValidationError={runValidationError}
                                />
                                <ActionAgentApprovals actionId={action.id} context={assignmentContext} />
                                <ActionAgentQuestionOwner actionId={action.id} context={assignmentContext} />
                            </Stack>
                        </ActionAgentInteractionVisibility>
                        <ActionScheduleOwner action={action} context={baseContext} store={scheduleStore} />
                        {action.type !== 'agent' ? (
                            <ActionRunStatusOwner actionId={action.id} context={assignmentContext} resultStore={resultStore} />
                        ) : null}
                        <ActionRunDisabledMessage action={action} settingsStore={settingsStore} />
                        {runValidationError ? (
                            <Typography color="error.main" role="alert" variant="caption">
                                {runValidationError}
                            </Typography>
                        ) : null}
                        {action.type !== 'agent' ? (
                            <ActionRunHistoryOwner store={historyStore} />
                        ) : null}
                    </Stack>
                    <ActionPopupBottomRow
                        action={action}
                        assignmentContext={assignmentContext}
                        conversationStore={conversationStore}
                        historyStore={historyStore}
                        inputStore={inputStore}
                        settingsStore={settingsStore}
                        resultStore={resultStore}
                        runValidationError={runValidationError}
                        scheduleStore={scheduleStore}
                    />
                </>}
            </MarkdownTypeaheadLayerProvider>
        </ResizablePopper>
    )
}

