import type { CardTypeConfig } from '../../data/data_types'
import { MarkdownFormatToolbarControls } from '../editor/markdown_format_toolbar_controls'
import { CardPropertiesControl } from '../text_view/card_properties_control'

interface CardPopupToolbarControlsProps {
    cardTypes: CardTypeConfig[]
    isFullscreen: boolean
    isMobile: boolean
    onToggleFullscreen: () => void
    statusColors: Map<string, string>
}

/** Formatting controls arranged for the card details popup. */
export function CardPopupToolbarControls(props: CardPopupToolbarControlsProps) {
    const { cardTypes, isFullscreen, isMobile, onToggleFullscreen, statusColors } = props
    const label = isFullscreen ? 'Exit fullscreen' : 'Fullscreen'

    return (
        <MarkdownFormatToolbarControls endControls={(
            <>
                <Box sx={{ flex: 1 }} />
                <CardPropertiesControl binding="board-card" cardTypes={cardTypes} statusColors={statusColors} />
                {!isMobile ? (
                    <Tooltip title={label}>
                        <IconButton aria-label={label} onClick={onToggleFullscreen} size="small" sx={{ height: 30, width: 30 }}>
                            {isFullscreen ? <FullscreenExit sx={{ fontSize: 17 }} /> : <Fullscreen sx={{ fontSize: 17 }} />}
                        </IconButton>
                    </Tooltip>
                ) : null}
            </>
        )} />
    )
}
import TuneOutlined from '@mui/icons-material/TuneOutlined'
import { IconButton, Tooltip } from '@mui/material'
import { useCallback, useState, type MouseEvent } from 'react'
import type { CardTypeConfig } from '../../data/data_types'
import { dialogService } from '../../services/dialog_service'
import { cardMarkdownDataSource, type CardBinding } from '../editor/card_markdown_data_source'
import { useActiveCard } from '../hooks/use_active_card'
import { CardPropertiesPanel } from './card_properties_panel'
import { CardPropertiesPopover } from './card_properties_popover'

interface CardPropertiesControlProps {
    binding: CardBinding
    cardTypes: CardTypeConfig[]
    statusColors: Map<string, string>
}

interface PropertiesAnchor {
    documentId: string
    element: HTMLElement
}

/** Icon-only Properties control shared by list and board card toolbars. */
export function CardPropertiesControl(props: CardPropertiesControlProps) {
    const { binding, cardTypes, statusColors } = props
    const card = useActiveCard(binding)
    const documentId = card?.header.internalId ?? null
    const [propertiesAnchor, setPropertiesAnchor] = useState<PropertiesAnchor | null>(null)
    const isOpen = !!documentId && propertiesAnchor?.documentId === documentId

    const handleOpen = useCallback((event: MouseEvent<HTMLElement>) => {
        try {
            const activeDocumentId = cardMarkdownDataSource.getActiveDocument(binding)?.getObject().header.internalId
            if (!activeDocumentId) throw new Error(`Cannot open card properties without an active ${binding} document`)

            setPropertiesAnchor({ documentId: activeDocumentId, element: event.currentTarget })
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Card properties could not be opened' })
        }
    }, [binding])
    const handleClose = useCallback(() => setPropertiesAnchor(null), [])

    if (!card || !documentId || !card.hasFrontmatter) return null

    return (
        <>
            <Tooltip title="Properties">
                <IconButton
                    aria-haspopup="dialog"
                    aria-label="Properties"
                    onClick={handleOpen}
                    size="small"
                    sx={{
                        bgcolor: isOpen ? 'custom.primaryBg' : 'transparent',
                        color: isOpen ? 'primary.main' : 'inherit',
                        height: 30,
                        width: 30,
                        '&:hover': { bgcolor: 'custom.track', color: 'primary.main' },
                    }}
                >
                    <TuneOutlined sx={{ fontSize: 17 }} />
                </IconButton>
            </Tooltip>
            <CardPropertiesPopover
                anchorElement={isOpen ? propertiesAnchor.element : null}
                onClose={handleClose}
                open={isOpen}
            >
                <CardPropertiesPanel
                    binding={binding}
                    cardTypes={cardTypes}
                    statusColors={statusColors}
                />
            </CardPropertiesPopover>
        </>
    )
}
import {
    Box, InputBase, MenuItem, Select, Typography,
    type SelectChangeEvent,
} from '@mui/material'
import DriveFileMoveOutlined from '@mui/icons-material/DriveFileMoveOutlined'
import EditOutlined from '@mui/icons-material/EditOutlined'
import LabelOutlined from '@mui/icons-material/LabelOutlined'
import PolicyOutlined from '@mui/icons-material/PolicyOutlined'
import ScheduleOutlined from '@mui/icons-material/ScheduleOutlined'
import TitleOutlined from '@mui/icons-material/TitleOutlined'
import { useState, type ChangeEvent, type KeyboardEvent } from 'react'
import { getCardType } from '../../data/action_context'
import { defaultColumnAccent, type CardTypeConfig } from '../../data/data_types'
import { cardMarkdownDataSource, type CardBinding } from '../editor/card_markdown_data_source'
import { useActiveCard } from '../hooks/use_active_card'

const AUTO_MERGE_POLICY_KEY = 'autoMerge'
const MANUAL_POLICY_VALUE = 'manual'
const AUTO_MERGE_POLICY_VALUE = 'autoMerge'

interface PropertyDraft {
    baseline: string
    documentId: string | null
    value: string
}

interface CardPropertiesPanelProps {
    binding: CardBinding
    cardTypes: CardTypeConfig[]
    statusColors: Map<string, string>
}

const rowSx = {
    alignItems: 'center',
    borderRadius: '6px',
    display: 'flex',
    gap: '10px',
    height: 36,
    px: '6px',
    '&:hover': { bgcolor: 'custom.track' },
}

const labelSx = {
    alignItems: 'center',
    color: 'custom.text3',
    display: 'flex',
    flexShrink: 0,
    fontSize: '12.5px',
    gap: '6px',
    width: 82,
}

const inputSx = {
    bgcolor: 'transparent',
    border: '1px solid transparent',
    borderRadius: '7px',
    flex: 1,
    height: 32,
    minWidth: 0,
    px: 1,
    '&:hover': { bgcolor: 'background.paper', borderColor: 'divider' },
    '&.Mui-focused': {
        bgcolor: 'background.paper',
        borderColor: 'primary.main',
        boxShadow: (theme: { palette: { custom: { primaryBg: string } } }) => `0 0 0 3px ${theme.palette.custom.primaryBg}`,
    },
}

/** Compact editor for user-facing card properties inside the toolbar popup. */
export function CardPropertiesPanel(props: CardPropertiesPanelProps) {
    const { binding, cardTypes, statusColors } = props
    const card = useActiveCard(binding)
    const documentId = card?.header.internalId ?? null
    const author = card?.header.author ?? null
    const title = card?.header.title ?? ''
    const authorValue = author ?? ''
    const [authorEdit, setAuthorEdit] = useState<PropertyDraft>({ baseline: authorValue, documentId, value: authorValue })
    const [titleEdit, setTitleEdit] = useState<PropertyDraft>({ baseline: title, documentId, value: title })
    const authorDraft = authorEdit.documentId === documentId && authorEdit.baseline === authorValue
        ? authorEdit.value
        : authorValue
    const titleDraft = titleEdit.documentId === documentId && titleEdit.baseline === title ? titleEdit.value : title
    const autoMergeEnabled = card?.header.policy[AUTO_MERGE_POLICY_KEY] ?? false
    const policyValue = autoMergeEnabled ? AUTO_MERGE_POLICY_VALUE : MANUAL_POLICY_VALUE
    const affects = card?.header.affects ?? []
    const affectsValue = affects.length > 0 ? affects.join(', ') : 'None'
    const statusValue = card?.header.status ?? 'None'
    const statusColor = card?.header.status
        ? statusColors.get(card.header.status) ?? defaultColumnAccent(0)
        : undefined
    const typeValue = card ? getCardType(cardTypes, card.header.id) ?? '' : ''

    const handleTitleChange = (event: ChangeEvent<HTMLInputElement>) => {
        setTitleEdit({ baseline: title, documentId, value: event.target.value })
    }

    const commitTitle = () => {
        const nextTitle = titleDraft.trim()
        if (nextTitle.length === 0) {
            setTitleEdit({ baseline: title, documentId, value: title })
            return
        }
        if (nextTitle !== title) cardMarkdownDataSource.updateActiveCardTitle(binding, nextTitle)
    }

    const handleTitleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
        if (event.key === 'Enter') event.currentTarget.blur()
        if (event.key === 'Escape') {
            setTitleEdit({ baseline: title, documentId, value: title })
            event.currentTarget.blur()
        }
    }

    const handleAuthorChange = (event: ChangeEvent<HTMLInputElement>) => {
        setAuthorEdit({ baseline: authorValue, documentId, value: event.target.value })
    }

    const commitAuthor = () => {
        if (authorDraft !== (author ?? '')) {
            cardMarkdownDataSource.updateActiveCardHeaderField(binding, 'author', authorDraft)
        }
    }

    const handleAuthorKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
        if (event.key === 'Enter') event.currentTarget.blur()
        if (event.key === 'Escape') {
            setAuthorEdit({ baseline: authorValue, documentId, value: authorValue })
            event.currentTarget.blur()
        }
    }

    const handlePolicyChange = (event: SelectChangeEvent) => {
        const shouldAutoMerge = event.target.value === AUTO_MERGE_POLICY_VALUE
        if (shouldAutoMerge !== autoMergeEnabled) cardMarkdownDataSource.toggleActiveCardPolicy(binding, AUTO_MERGE_POLICY_KEY)
    }

    const handleTypeChange = (event: SelectChangeEvent) => {
        const nextType = event.target.value
        if (nextType !== typeValue) void cardMarkdownDataSource.updateActiveCardType(binding, nextType)
    }

    if (!card) return null

    return (
        <Box
            aria-label="Card properties"
            sx={{maxWidth: 720, width: '100%'}}
        >
            <Box
                sx={{
                    alignItems: 'center', borderBottom: '1px solid', borderColor: 'divider',
                    display: 'flex', mb: 1.25, minHeight: 32, pb: 1.25, px: 0.75,
                }}
            >
                <Typography
                    component="h2"
                    sx={{ color: 'custom.colHead', fontSize: 11, fontWeight: 700, letterSpacing: '0.7px', lineHeight: 1 }}
                    variant="overline"
                >
                    Properties
                </Typography>
                <Box sx={{ flex: 1 }} />
                <Box
                    component="span"
                    sx={{
                        bgcolor: 'custom.primaryBg', borderRadius: '4px', color: 'primary.main',
                        fontFamily: 'monospace', fontSize: 11, fontWeight: 600, px: 0.75, py: 0.25,
                    }}
                >
                    {card.header.id}
                </Box>
            </Box>
            <Box sx={{ columnGap: '24px', display: 'grid', gridTemplateColumns: '1fr 1fr', rowGap: '2px' }}>
                <Box sx={{ ...rowSx, gridColumn: '1 / -1', height: 40 }}>
                    <Box sx={labelSx}><TitleOutlined sx={{ fontSize: 14 }} />Title</Box>
                    <InputBase
                        fullWidth
                        inputProps={{ 'aria-label': 'Card title' }}
                        onBlur={commitTitle}
                        onChange={handleTitleChange}
                        onKeyDown={handleTitleKeyDown}
                        sx={{ ...inputSx, '& input': { fontSize: 14, fontWeight: 600, p: 0 } }}
                        value={titleDraft}
                    />
                </Box>
                <Box sx={rowSx}>
                    <Box sx={labelSx}><ScheduleOutlined sx={{ fontSize: 14 }} />Status</Box>
                    <Box
                        sx={{
                            alignItems: 'center', bgcolor: 'custom.track', border: '1px solid', borderColor: 'divider',
                            borderRadius: 99, color: 'text.secondary', display: 'inline-flex', fontSize: 12,
                            fontWeight: 600, gap: 0.75, height: 22, px: '10px',
                        }}
                    >
                        <Box sx={{ bgcolor: statusColor ?? 'custom.text4', borderRadius: '50%', height: 7, width: 7 }} />
                        {statusValue}
                    </Box>
                </Box>
                <Box sx={rowSx}>
                    <Box sx={labelSx}><LabelOutlined sx={{ fontSize: 14 }} />Type</Box>
                    <Select
                        aria-label="Card type"
                        onChange={handleTypeChange}
                        size="small"
                        sx={{
                            bgcolor: 'custom.track', borderRadius: '7px', color: 'text.secondary', fontSize: '12.5px',
                            fontWeight: 500, height: 24,
                            '& .MuiOutlinedInput-notchedOutline': { borderColor: 'divider' },
                            '&:hover .MuiOutlinedInput-notchedOutline': { borderColor: 'custom.borderHover' },
                            '& .MuiSelect-select': { py: 0, pl: '10px', pr: '26px' },
                            '& .MuiSelect-icon': { color: 'custom.text4', fontSize: 17 },
                        }}
                        value={typeValue}
                    >
                        {typeValue.length === 0 ? <MenuItem disabled value="">Unknown</MenuItem> : null}
                        {cardTypes.map(({ label, type }) => <MenuItem key={type} value={type}>{label}</MenuItem>)}
                    </Select>
                </Box>
                <Box sx={{ ...rowSx, height: 40 }}>
                    <Box sx={labelSx}><EditOutlined sx={{ fontSize: 14 }} />Author</Box>
                    <InputBase
                        fullWidth
                        inputProps={{ 'aria-label': 'Card author' }}
                        onBlur={commitAuthor}
                        onChange={handleAuthorChange}
                        onKeyDown={handleAuthorKeyDown}
                        sx={{ ...inputSx, '& input': { fontSize: 13, p: 0 } }}
                        value={authorDraft}
                    />
                </Box>
                <Box sx={rowSx}>
                    <Box sx={labelSx}><DriveFileMoveOutlined sx={{ fontSize: 14 }} />Affects</Box>
                    <Typography
                        noWrap
                        sx={{ color: affects.length > 0 ? 'text.primary' : 'custom.text4', fontSize: 13, minWidth: 0 }}
                        title={affectsValue}
                    >
                        {affectsValue}
                    </Typography>
                </Box>
                <Box sx={rowSx}>
                    <Box sx={labelSx}><PolicyOutlined sx={{ fontSize: 14 }} />Policy</Box>
                    <Select
                        aria-label="Card policy"
                        onChange={handlePolicyChange}
                        size="small"
                        sx={{
                            bgcolor: 'custom.track', borderRadius: '7px', color: 'text.secondary', fontSize: '12.5px',
                            fontWeight: 500, height: 24,
                            '& .MuiOutlinedInput-notchedOutline': { borderColor: 'divider' },
                            '&:hover .MuiOutlinedInput-notchedOutline': { borderColor: 'custom.borderHover' },
                            '& .MuiSelect-select': { py: 0, pl: '10px', pr: '26px' },
                            '& .MuiSelect-icon': { color: 'custom.text4', fontSize: 17 },
                        }}
                        value={policyValue}
                    >
                        <MenuItem value={MANUAL_POLICY_VALUE}>Manual</MenuItem>
                        <MenuItem value={AUTO_MERGE_POLICY_VALUE}>Auto-merge</MenuItem>
                    </Select>
                </Box>
            </Box>
        </Box>
    )
}
import { Box, Button, Divider, Stack, Typography } from '@mui/material'
import { useEffect, useState, type MouseEvent } from 'react'
import type { DiffFile, WorktreeDiffResult } from '../../data/electron_action_bridge'
import { cardCommitLabel, loadCardBodyDiff, type CardBodyDiff, type CardCommit } from '../../services/actions/card_commit_history'
import { markdownParsingService } from '../../services/data/markdown_parsing_service'
import { dialogService } from '../../services/dialog_service'
import { worktreeService } from '../../services/project/worktree_service'
import type { DiffCommitReference } from '../../services/data/diff_service'
import { DiffView } from '../actions/conversation/diff_view'
import { MarkdownEditor } from '../editor/markdown_editor'
import type { MarkdownBindingKind } from '../editor/markdown_data_source'
import { useActiveCard } from '../hooks/use_active_card'

export type CardDiffSelection =
    | { commit: CardCommit, kind: 'commit' }
    | { kind: 'worktree' }

interface CardCommitDiffPanelProps {
    binding: Exclude<MarkdownBindingKind, 'list-action'>
    onExit: () => void
    selection: CardDiffSelection
}

interface LoadedWorktreeDiff {
    bodyDiff: CardBodyDiff | null
    cardFile: DiffFile | null
    result: WorktreeDiffResult
}

interface KeyedValue<Value> {
    key: string
    value: Value
}

function ignoreReadOnlyChange() {
    // Diff editor is read-only and intentionally disconnected from persistence.
}

function diffReference(commit: CardCommit): DiffCommitReference {
    return {
        branch: commit.branch,
        commit: commit.commit,
        filePaths: commit.filePaths,
    }
}

function worktreeBodyDiff(file: DiffFile): CardBodyDiff {
    const oldExists = file.changeType !== 'added'
    const newExists = file.changeType !== 'deleted'

    return {
        newBody: newExists ? markdownParsingService.parse(file.newValue).body : '',
        newExists,
        oldBody: oldExists ? markdownParsingService.parse(file.oldValue).body : '',
        oldExists,
    }
}

function normalizeWorktreeDiff(result: WorktreeDiffResult, cardPath: string): LoadedWorktreeDiff {
    const cardFile = result.files.find((file) => file.path === cardPath || file.oldPath === cardPath) ?? null

    return { bodyDiff: cardFile ? worktreeBodyDiff(cardFile) : null, cardFile, result }
}

function changedFileLabel(file: DiffFile) {
    return file.changeType === 'renamed' && file.oldPath ? `${file.oldPath} â€” ${file.path}` : file.path
}

/** Read-only card body diff plus navigation to every other changed file. */
export function CardCommitDiffPanel(props: CardCommitDiffPanelProps) {
    const { binding, onExit, selection } = props
    const commit = selection.kind === 'commit' ? selection.commit : null
    const isWorktree = selection.kind === 'worktree'
    const card = useActiveCard(binding)
    const cardPath = card?.path ?? null
    const historicalTouchesCurrentPath = !!cardPath && !!commit?.filePaths.includes(cardPath)
    const loadKey = `${isWorktree ? 'worktree' : commit?.commit ?? 'missing'}:${cardPath ?? 'missing'}`
    const [bodyDiffState, setBodyDiffState] = useState<KeyedValue<CardBodyDiff> | null>(null)
    const [errorState, setErrorState] = useState<KeyedValue<Error> | null>(null)
    const [worktreeDiffState, setWorktreeDiffState] = useState<KeyedValue<LoadedWorktreeDiff> | null>(null)
    const [selectedOtherPathState, setSelectedOtherPathState] = useState<KeyedValue<string> | null>(null)
    const bodyDiff = bodyDiffState?.key === loadKey ? bodyDiffState.value : null
    const error = errorState?.key === loadKey ? errorState.value : null
    const loadedWorktreeDiff = worktreeDiffState?.key === loadKey ? worktreeDiffState.value : null
    const selectedOtherPath = selectedOtherPathState?.key === loadKey ? selectedOtherPathState.value : null
    const selectOtherPath = (event: MouseEvent<HTMLButtonElement>) => {
        try {
            const { path } = event.currentTarget.dataset
            if (!path) throw new Error('Cannot select an empty changed-file path')
            setSelectedOtherPathState({ key: loadKey, value: path })
        } catch (caught) {
            dialogService.error(caught, { fallbackMessage: 'Changed file could not be selected' })
        }
    }

    useEffect(() => {
        let active = true
        if (!cardPath) return () => { active = false }

        if (isWorktree) {
            void worktreeService.generateCardWorktreeDiff(cardPath).then((result) => {
                if (active) setWorktreeDiffState({ key: loadKey, value: normalizeWorktreeDiff(result, cardPath) })
            }).catch((loadError: unknown) => {
                if (!active) return
                const nextError = loadError instanceof Error ? loadError : new Error('Could not load worktree diff')
                setErrorState({ key: loadKey, value: nextError })
                dialogService.error(nextError, { fallbackMessage: 'Could not load worktree diff' })
            })

            return () => { active = false }
        }

        if (!commit || commit.available === false || !historicalTouchesCurrentPath) return () => { active = false }
        void loadCardBodyDiff(commit, cardPath).then((nextDiff) => {
            if (active) setBodyDiffState({ key: loadKey, value: nextDiff })
        }).catch((loadError: unknown) => {
            if (active) {
                const nextError = loadError instanceof Error ? loadError : new Error('Could not load card body diff')
                setErrorState({ key: loadKey, value: nextError })
            }
        })

        return () => { active = false }
    }, [cardPath, commit, historicalTouchesCurrentPath, isWorktree, loadKey])

    if (!cardPath) return null

    const worktreeCardFile = loadedWorktreeDiff?.cardFile ?? null
    const touchesCurrentPath = isWorktree ? !!worktreeCardFile : historicalTouchesCurrentPath
    const displayedBodyDiff = isWorktree ? loadedWorktreeDiff?.bodyDiff ?? null : bodyDiff
    const hasBodyChanges = !!displayedBodyDiff && displayedBodyDiff.oldBody !== displayedBodyDiff.newBody
    const displayError = commit?.available === false
        ? new Error('Commit is no longer available in this repository')
        : error
    const historicalOtherPaths = commit?.filePaths.filter((filePath) => filePath !== cardPath) ?? []
    const worktreeOtherFiles = loadedWorktreeDiff?.result.files.filter((file) => file !== worktreeCardFile) ?? []
    const otherFileCount = isWorktree ? worktreeOtherFiles.length : historicalOtherPaths.length
    const loading = !displayError && (isWorktree ? !loadedWorktreeDiff : touchesCurrentPath && !displayedBodyDiff)

    return (
        <Box aria-label={isWorktree ? 'Card worktree diff' : 'Card commit diff'} role="region" sx={{ display: 'flex', flex: 1, flexDirection: 'column', minHeight: 0, overflowY: 'auto' }}>
            <Box sx={{ alignItems: 'center', borderBottom: '1px solid', borderColor: 'divider', display: 'flex', gap: 1, p: 1.5 }}>
                <Box sx={{ flex: 1, minWidth: 0 }}>
                    <Typography variant="subtitle2">{isWorktree ? 'Current worktree changes' : cardCommitLabel(commit!.record)}</Typography>
                    <Typography color="text.secondary" variant="caption">
                        {isWorktree ? 'Current repository state' : `${new Date(commit!.committedAt).toLocaleString()} Â· ${commit!.commit.slice(0, 7)}`}
                    </Typography>
                </Box>
                <Button onClick={onExit} size="small" variant="outlined">Exit diff</Button>
            </Box>
            {displayError ? <Typography color="error" role="alert" sx={{ p: 2 }}>{displayError.message}</Typography> : null}
            {loading ? <Typography sx={{ p: 2 }}>Loading diffâ€¦</Typography> : null}
            {touchesCurrentPath && displayedBodyDiff && !hasBodyChanges ? (
                <Typography color="text.secondary" sx={{ p: 2 }}>No body changes in this {isWorktree ? 'worktree' : 'commit'}</Typography>
            ) : null}
            {touchesCurrentPath && displayedBodyDiff && hasBodyChanges ? (
                <MarkdownEditor
                    diffMarkdown={displayedBodyDiff.oldBody}
                    hideToolbar
                    key={commit?.commit ?? 'current-worktree'}
                    markdown={displayedBodyDiff.newBody}
                    onChange={ignoreReadOnlyChange}
                    readOnly
                    viewMode="diff"
                />
            ) : null}
            {!loading ? <Divider /> : null}
            {!loading ? (
                <Stack spacing={0.5} sx={{ p: 1.5 }}>
                    <Typography variant="subtitle2">Also changed ({otherFileCount})</Typography>
                    {isWorktree ? worktreeOtherFiles.map((file) => (
                        <Button data-path={file.path} key={`${file.oldPath ?? ''}:${file.path}`} onClick={selectOtherPath} sx={{ justifyContent: 'flex-start' }} variant="text">
                            {changedFileLabel(file)}
                        </Button>
                    )) : historicalOtherPaths.map((filePath) => (
                        <Button data-path={filePath} key={filePath} onClick={selectOtherPath} sx={{ justifyContent: 'flex-start' }} variant="text">
                            {filePath}
                        </Button>
                    ))}
                    {otherFileCount === 0 ? <Typography color="text.secondary" variant="body2">No other files changed.</Typography> : null}
                </Stack>
            ) : null}
            {selectedOtherPath && commit ? (
                <Box sx={{ p: 1.5 }}>
                    <DiffView commitReference={diffReference(commit)} initialPath={selectedOtherPath} />
                </Box>
            ) : null}
            {selectedOtherPath && loadedWorktreeDiff ? (
                <Box sx={{ p: 1.5 }}>
                    <DiffView initialPath={selectedOtherPath} label="Worktree diff" result={loadedWorktreeDiff.result} />
                </Box>
            ) : null}
        </Box>
    )
}
import { useCallback, useSyncExternalStore } from 'react'
import type { Card } from '../../data/data_types'
import { cardMarkdownDataSource, type CardMarkdownDataSource } from '../editor/card_markdown_data_source'
import type { MarkdownBindingKind } from '../editor/markdown_data_source'

type CardBinding = Exclude<MarkdownBindingKind, 'list-action'>

/** Subscribe to the card currently assigned to one card-editor binding. */
export function useActiveCard(
    binding: CardBinding,
    dataSource: CardMarkdownDataSource = cardMarkdownDataSource,
): Card | null {
    const subscribe = useCallback((onStoreChange: () => void) => {
        dataSource.addEventListener('activeDocumentChanged', onStoreChange)
        dataSource.addEventListener('cardsChanged', onStoreChange)

        return () => {
            dataSource.removeEventListener('activeDocumentChanged', onStoreChange)
            dataSource.removeEventListener('cardsChanged', onStoreChange)
        }
    }, [dataSource])
    const getSnapshot = useCallback(() => dataSource.getActiveCard(binding), [binding, dataSource])

    return useSyncExternalStore(subscribe, getSnapshot, getSnapshot)
}

